# Texto del artículo en inglés. Lo usa construir_articulo.py (funciones P, B, H1, H2, BL, table, figure).
# Las tablas de la revisión se leen de R/resultados (scripts 11, 12 y 13) para no transcribir números a mano.
import csv, unicodedata
RES = os.path.join(AQUI, '..', 'resultados')
leer = lambda f: list(csv.DictReader(open(os.path.join(RES, f), encoding='utf8')))
f1 = lambda x, n=1: f"{float(x):.{n}f}"
sin_tilde = lambda t: unicodedata.normalize('NFKD', t).encode('ascii', 'ignore').decode()

BENCH = {r['modelo']: r for r in leer('13_benchmarks.csv')}
NOMBRE_EN = {"XGBoost": "XGBoost", "GAM": "GAM", "Bosque aleatorio": "Random forest", "Logística": "Logistic regression",
             "Logística penalizada (elastic net)": "Elastic-net logistic"}
filas_bench = [[NOMBRE_EN[k], f1(BENCH[k]['auc_roc'], 3), f"{f1(BENCH[k]['auc_roc_inf'],3)}–{f1(BENCH[k]['auc_roc_sup'],3)}",
                f1(BENCH[k]['auc_pr'], 3), f"{f1(BENCH[k]['auc_pr_inf'],3)}–{f1(BENCH[k]['auc_pr_sup'],3)}"]
               for k in ["XGBoost", "GAM", "Bosque aleatorio", "Logística", "Logística penalizada (elastic net)"]]
SENS = leer('13_sensibilidad_umbral.csv')
filas_sens = [[f1(r['umbral'], 2) if float(r['umbral']) != 0.175 else "0.175", f1(r['brecha_pct_todos']), f1(r['precision']),
               f1(r['solicito_en_brecha']), f1(r['spearman_dptos'], 2)] for r in SENS]
DEPF = leer('13_departamentos_datos_completos.csv')
def filas_dep(nombre):
    return [[nombre(r['DEPARTAMENTO']), f"{int(r['n']):,}", f"{int(r['conglomerados']):,}", f1(r['tasa_credito']), f1(r['brecha']),
             f"{round(float(r['inf']))}–{round(float(r['sup']))}"] for r in DEPF]
FULL = leer('13_datos_completos.csv')[0]
ASIG = {(r['K'], r['regla']): r for r in leer('13_asignacion_cruzada.csv')}
def celda_asig(K, regla):
    r = ASIG[(K, regla)]; return f"{round(float(r['cruzado']))} ({round(float(r['inf']))}–{round(float(r['sup']))})"
LENDERS = leer('14_prestamistas_anio.csv')
filas_lend = [[r['ANIO'][:4], f1(r['por100_pub']), f1(r['por100_cmac']), f1(r['por100_priv']), f1(r['por100_coop']), f1(r['por100_inf']), f1(r['acceso'])] for r in LENDERS]
filas_asig = [[f"{int(K):,}", celda_asig(K, 'ganancia'), celda_asig(K, 'probabilidad'), celda_asig(K, 'azar'), str(round(float(ASIG[(K, 'ganancia')]['mismo_modelo'])))]
              for K in ['500', '1000', '2000']]

TITLE="Agricultural Credit Access in Peru: Targeting and Scenario Analysis with Interpretable Machine Learning"
c=[]
c.append('<w:p><w:pPr><w:pStyle w:val="Abstract"/><w:rPr><w:i/><w:iCs/></w:rPr></w:pPr><w:r><w:rPr><w:i/><w:iCs/></w:rPr><w:t>Abstract</w:t></w:r><w:r><w:t xml:space="preserve">—'
 + escape("Only about one in ten small and medium agricultural producers in Peru obtains credit. With 49,837 producers from seven rounds of the National Agricultural Survey (2016 to 2025), we model whether a producer applied for and obtained credit in the previous 12 months, and we use the model for targeting and for model-based what-if scenarios. Fourteen of 35 candidate predictors were kept. On test clusters not used for training, XGBoost reached an area under the ROC curve of 0.798 (95 percent bootstrap interval 0.780 to 0.814) and kept it out of time (0.804); a generalized additive model and a logistic regression performed about as well, so the information in the survey, not the algorithm, limits accuracy. Access depends mainly on applying: 13 percent of producers applied and 92 percent of applicants obtained credit. Ranking producers by predicted probability places 54 percent of credit holders in the top 20 percent. A propensity gap of 16.4 percent of producers, without credit but with a high predicted probability, almost never applied (2 percent) and is largest in the departments where credit is already common. When public lending fell in 2019, other lenders did not take its clients, and public lenders mainly reach association members rather than the producers least likely to obtain credit. In the scenarios, association membership is associated with the largest increase in the weighted national rate, from 10.3 to 16.4 percent; these simulations are not causal estimates. Evaluated with an independent model, choosing non-members by simulated gain did no better than choosing them by predicted probability, and both reached about 1.6 times the new credit holders of a random choice.")
 + '</w:t></w:r></w:p>')
c.append(P('Keywords', "Keywords—agricultural credit, financial inclusion, interpretable machine learning, SHAP, targeting, survey data"))

c.append(H1("Introduction"))
c.append(B("Access to credit allows agricultural producers to buy inputs, adopt technology and absorb shocks, yet formal credit reaches only a minority of small farms in developing countries. In Peru, the penetration of financial services in agriculture has remained low for decades, and the agrarian credit market has been described as incomplete [[wiener]]. Studies based on household data have shown that credit constraints lower farm productivity and that many producers who could qualify for a loan do not apply because of the risk involved [[guirkinger,boucher]]. Lenders and public programs that promote rural financial inclusion therefore need to know which producers are most likely to obtain credit and under which conditions."))
c.append(B("Most empirical work on this topic is explanatory. With the National Agricultural Survey for 2015 to 2019, farm size turned out to be a main determinant: being a smallholder reduces the probability of access to credit [[ramos24]]. Personal and managerial characteristics of smallholders also shape their financial behaviour [[ramos26]], and socioeconomic factors determine the financial inclusion of Peruvian households in general [[quispe]]. Using census data and propensity score matching, small coffee farmers who belong to an association were found to have more than twice the odds of requesting credit [[paredes]]."))
c.append(B("Machine learning adds prediction. Gradient boosting models capture nonlinear relations and interactions in tabular data [[chen,friedman]], and explanation methods such as SHAP make their predictions interpretable [[lundberg17,lundberg20]]. With farm survey data from the United States, several machine learning models predicted the demand for new credit better than standard econometric approaches, although not in every case [[ifft]]. In Peru, machine learning has been used to predict the financial inclusion of the general population [[maehara]] and to assess rural microcredit applications in a microfinance institution [[condori21,condori22]]. Interpretable gradient boosting has also been applied to identify credit-constrained rural households in China [[liu]], to score smallholder farmers in India [[jonnalagadda]], and to study financial inclusion [[liliu]] and informal borrowing [[pinit]]."))
c.append(B("These studies predict or explain access but do not use the model to support decisions. Prescriptive analytics seeks the best course of action and is considered the next step after descriptive and predictive analytics [[lepenioti]]; in development policy, machine learning has been used to target social assistance [[aiken]]. We move in that direction with two uses of the model: ranking producers for targeting, and model-based what-if scenarios for four actionable conditions. Because the data are observational, the scenarios describe associations learned by the model and not causal effects, and we evaluate the targeting rules with a model independent of the one that selects producers."))
c.append(B("The paper has four parts. We first define the outcome and build the modeling data from the National Agricultural Survey (ENA, by its Spanish acronym) of Peru [[inei]]. We then select predictors, fit XGBoost and compare it with four other models. Third, we validate the results with bootstrap intervals, an out-of-time test, leave-one-region-out tests and a refit on all cleaned data. Finally, we use the model for targeting, for a propensity gap analysis by department, for scenarios and for a budget-constrained allocation, and we compare public and private lenders. All the analysis was done in R."))

c.append(H1("Data and Methods"))
c.append(H2("Data and Outcome"))
c.append(B("The ENA is an annual survey of agricultural producers conducted by the National Institute of Statistics and Informatics [[inei]]. We kept the units that the ENA identifies as small and medium producers, which excludes large producers and companies. We used seven rounds: 2016, 2017, 2019 and 2022 to 2025. We excluded the 2014, 2015 and 2018 rounds because they lack area, experience and parcel variables. There was no survey in 2020, and the 2021 round has no credit module."))
c.append(B("The questionnaire asks whether the producer applied for any credit in the previous 12 months (question P901) and, if so, whether the credit was obtained (P902). The outcome equals one when the producer applied and obtained credit, and zero when the producer did not apply or was denied. In the sample, 13.0 percent applied and 91.9 percent of applicants obtained credit, so access depends mainly on applying. The outcome covers any lender. Among credit holders, 95 percent borrowed from at least one formal or semiformal source (municipal savings banks 30 percent, private banks 24, Agrobanco 20, finance companies 11, cooperatives 8 and rural savings banks 7), and 4.3 percent only from moneylenders or shops."))
c.append(B("The ENA sample is drawn in two stages: INEI first selects small areas and then interviews the producers in each of them. Until 2022 these areas were clusters of neighboring rural dwellings; from 2023 INEI switched to an area frame whose units are map segments. We call both units clusters. Our sample contains 7,491 of them: 1,202 clusters from 2016 to 2022, with 21.5 producers on average, and 6,289 segments from 2023 to 2025, with 3.8. Each cluster lies in a single department. Producers in a cluster share climate, markets and nearby lenders, and in 67 percent of the clusters no producer holds credit. Clusters are not predictors: we use them to draw the sample, to split the data and to define the cross-validation folds."))
c.append(B("The rounds were harmonized by variable name: 1,324 of the 1,329 variables of 2025 have the same name as in 2014 to 2024, and we used only areas recorded in hectares. The change of sampling frame in 2023 roughly doubles the median farm area, so we test the model out of time. The ENA has no panel identifier. Producers interviewed again within the same design keep their cluster code and therefore stay on one side of the split, but producers interviewed before and after 2023 cannot be linked."))
c.append(H2("Modeling Sample"))
c.append(B("We built the modeling sample in four steps (Table I). We first reduced the survey records, which come one per crop, parcel or household member, to one row per producer and year. We then kept the complete interviews of small and medium producers in the seven rounds who answered the credit question, which gives 217,535 producers. Eight consistency rules removed 20,969 records, for example ages below 18, harvested areas more than three times the total area, or missing predictors; we imputed nothing. The excluded records had a credit rate of 6.4 percent, against 11.8 percent among those kept. The largest group excluded were producers without harvest or livestock in the period, so our results refer to producers with agricultural activity and complete records."))
c.append(B("We then drew a sample of about 50,000 producers, a size fixed in advance for this study, by selecting whole clusters at random within each combination of year and natural region, in proportion to its size. We adjusted the expansion factors so that the sample represents the cleaned population: the weighted credit rate is 10.10 percent in the cleaned population and 10.13 percent in the sample. To check that the subsample does not change the conclusions, we repeated the model and the department analysis with all 196,566 cleaned producers. Finally, we split the sample into training and test sets by cluster, so no cluster contributes to both sets. A split that ignores the dependence between neighbors leaks information and gives overoptimistic results [[kapoor,ploton]]."))
c.append(table("Construction of the Modeling Sample", ["Step","Producers","Clusters","With credit (%)"],
   [["One row per producer and year, 2014–2025","341,211","n/a","n/a"],["Study population (7 rounds, small and medium)","217,535","n/a","11.2"],
    ["Removed by the consistency rules","20,969","n/a","6.4"],["Cleaned population","196,566","29,498","11.8"],["Modeling sample","49,837","7,491","11.9"],["Training set","39,868","6,005","11.9"],["Test set","9,969","1,486","11.9"]], [124,46,40,42],
   "Clusters: sampling units of the survey (clusters of dwellings until 2022, map segments from 2023). Unweighted rates; the weighted national rate is 10.1 percent."))
c.append(B("Natural region and department come from the survey itself. INEI classifies each surveyed area as coast, highlands or rainforest and records its department, one of 25 first-level divisions (24 departments and Callao). The sample has 10,401 producers on the coast, 29,143 in the highlands and 10,293 in the rainforest. Both variables enter the model as categorical predictors, with one indicator per category. We did not fit separate regional models: every regional result applies the national model and averages its predictions over the producers of each region."))
c.append(H2("Variable Selection"))
c.append(B("Thirty-five candidate predictors describe the producer (age, education, household size), the farm (areas, parcels, irrigation, livestock), practices (fertilizers, pesticides, technical assistance), market links (share of crops sold, sales destination), organization (association membership) and location (natural region and department). We selected variables in three steps, using only the training set."))
c.append(BL("Importance. We fitted an XGBoost model with five-fold cross-validation grouped by cluster and ranked each variable by its mean absolute SHAP value [[lundberg17]] on the held-out folds."))
c.append(BL("Redundancy. For every pair of variables with an absolute Spearman correlation of 0.70 or more, we kept only the more important one. This removed five variables, among them years of experience, which is correlated with age (0.72), and left 30."))
c.append(BL("Parsimony. We refitted the model with the k most important of the 30 remaining variables, for k from 5 to 30, and chose the smallest k whose cross-validated performance lies within one standard error of the best [[hastie]]."))
c.append(H2("Models"))
c.append(B("The main classifier is XGBoost [[chen]] trained through the caret package [[kuhn]]. We wrote a custom caret method because the built-in one does not tune the L1 and L2 penalties, and tuned nine hyperparameters by random search over 40 combinations, each evaluated with the same grouped five-fold cross-validation. The selection metric was the area under the precision-recall curve (AUC-PR), which is more informative than the ROC curve when the positive class is rare [[saito]]. We did not resample to correct class imbalance, because resampling before the data are split inflates performance [[jonnalagadda]]. The classification threshold is the value that maximizes the F1 score on the out-of-fold predictions. We used the test set once, after all choices had been made."))
c.append(B("We compared XGBoost with four models fitted to the same 14 predictors and the same training set: a logistic regression, with harvested and total area in logarithms and age in decades, examined with the easystats packages [[ludecke]]; an elastic-net logistic regression with the penalty chosen by grouped cross-validation [[friedman10]]; a random forest of 500 trees [[wright]]; and a generalized additive model with smooth terms for the continuous predictors [[wood]]. For the logistic regression we report odds ratios with standard errors robust to clustering [[zeileis]]. We report the area under the ROC curve (AUC-ROC), AUC-PR, the Matthews correlation coefficient (MCC) [[chicco]], recall, precision, specificity and the Brier score. Models are fitted without survey weights, as is usual for prediction; rates that describe the national population are weighted with the expansion factors and are labeled as such. Data handling and graphics used the tidyverse [[wickham]]."))
c.append(H2("Lenders"))
c.append(B("Question P903 records who provided the credit. We grouped lenders into five types: national public lenders (Agrobanco and State programs); municipal savings banks, which are owned by municipalities but run as commercial entities regulated by the banking supervisor; regulated private lenders (banks, rural savings banks and finance companies); cooperatives and NGOs; and informal lenders (shops and moneylenders). Producers may report more than one type, and 5.4 percent did. With all 196,566 cleaned producers and their expansion factors, we computed the borrowers of each type per 100 producers by year, region and department. We compared the clients of public and private lenders with a logistic regression among producers who used a single type, with the 14 predictors except department, year indicators and cluster-robust standard errors, and we placed each client on the propensity scale with the out-of-fold predictions of the full-data refit."))
c.append(B("To check whether other lenders replaced Agrobanco when its lending fell, we fitted a logistic model of borrowing from Agrobanco among the 2016 and 2017 borrowers, scored every producer with it, and followed over time the quarter of producers whose profile most resembled Agrobanco clients."))
c.append(H2("Validation"))
c.append(B("Besides the grouped cross-validation and the single use of the test set, we checked the results in five ways."))
c.append(BL("Uncertainty. We computed 95 percent intervals for the test metrics, and for the differences between models, from 1,000 bootstrap resamples of test clusters."))
c.append(BL("Calibration. We estimated the calibration intercept and slope by regressing the outcome on the logit of the predicted probability, and the mean absolute gap between predicted and observed rates over deciles."))
c.append(BL("Time. We refitted the model with the selected configuration on the 2016 to 2023 rounds and evaluated it on 2024 and 2025."))
c.append(BL("Space. We left out one natural region at a time, refitted the model on the other two and evaluated it on the omitted region."))
c.append(BL("Full data. We refitted the selected configuration with five-fold cross-validation grouped by cluster on all 196,566 cleaned producers."))
c.append(B("The variables and hyperparameters were chosen with training data from all years and regions, so the time and space checks reuse those choices. This is a mild form of leakage that makes both checks somewhat optimistic."))
c.append(H2("Targeting and Scenario Analysis"))
c.append(B("For targeting, we ranked the test producers by predicted probability and computed the share of credit holders captured at each coverage level. We call propensity gap the producers without credit whose predicted probability is at or above the classification threshold. By construction these are the false positives of the model, and they resemble credit holders because they were selected for having a high predicted probability; we therefore use the survey to ask whether they applied, and we report how the gap changes with the threshold."))
c.append(B("For departments we used the full-data refit: each of the 196,566 producers receives an out-of-fold prediction, and for each department we computed the credit rate and the share of its producers in the propensity gap, with 95 percent intervals from 300 bootstrap resamples of clusters within the department. The full data have 3,407 to 13,407 producers and 290 to 2,475 clusters per department. Callao, with a single producer, is left out. The test-set estimates serve as a check."))
c.append(B("For the scenarios, we switched on one actionable condition only for the test producers who lack it, kept every other variable unchanged, and recomputed the mean predicted probability, unweighted and weighted. The four conditions are association membership, sales to regional or Lima markets, irrigation on all crops and fertilizer use. Intervals come from bootstrap resamples of test clusters and do not include the uncertainty of the model."))
c.append(B("Finally, we posed an allocation problem: a program can promote association among K producers who have no credit and are not members. We compared three rules: choosing the K largest simulated gains in probability, choosing the K highest predicted probabilities, and choosing at random. Selecting and evaluating with the same model rewards its own errors, so we used cross-fitting. We trained two models on disjoint halves of the training clusters; one model selects the producers and the other estimates their gain, and the result is averaged over both orders, with intervals from 1,000 bootstrap resamples of test clusters."))

c.append(H1("Results"))
c.append(H2("Predictive Performance"))
c.append(B("Cross-validated AUC-PR is 0.340 with 14 variables and peaks at 0.347 with 20, within one standard error, so we kept 14 variables. The model with all 35 candidates, evaluated separately, gives 0.348, so the discarded variables add almost nothing. The selected configuration has 604 trees, a learning rate of 0.0235, a maximum depth of 6, a minimum child weight of 4.8, row and column subsampling of 0.62 and 0.57, a minimum loss reduction (gamma) of 4.08, an L2 penalty of 0.16 and an L1 penalty of 0.22. Its cross-validated AUC-PR is 0.349 (standard deviation 0.025) and its AUC-ROC 0.790 (0.008). The F1-optimal threshold is 0.175."))
c.append(table("Test Set Performance (9,969 Producers)", ["Metric","XGBoost","Logistic","Constant"],
   [["AUC-ROC","0.798","0.791","0.500"],["AUC-PR","0.367","0.359","0.119"],["MCC","0.307","0.308","n/a"],["F1 score","0.396","0.400","n/a"],["Recall","0.588","0.524","0.000"],
    ["Precision","0.299","0.323","n/a"],["Specificity","0.814","0.852","1.000"],["Brier score","0.089","0.090","0.105"]], [70,56,56,56],
   "Constant: every producer receives the training prevalence (0.119) as probability; with the 0.175 threshold all are classified as without credit, so precision, F1 and MCC are undefined."))
c.append(B("On the test set (Table II), XGBoost reaches an AUC-ROC of 0.798 and an AUC-PR of 0.367, three times the prevalence of 0.119. It identifies 698 of the 1,187 credit holders (59 percent) and 7,146 of the 8,782 producers without credit (81 percent). Performance is stable across years (AUC-ROC from 0.754 to 0.827) and regions (0.761 to 0.787), and the training AUC-ROC of 0.823 is close to the test value. Studies with other data report AUC-ROC values of 0.783 for credit access of smallholders in India [[jonnalagadda]] and 0.652 for credit constraints of rural households in China [[liu]]; since data and outcomes differ, these values are not directly comparable with ours."))
c.append(B("Table III compares the five models. The generalized additive model, the random forest and both logistic regressions reach AUC-ROC values between 0.791 and 0.796 and AUC-PR values between 0.354 and 0.371, and all have a Brier score of 0.089 or 0.090. XGBoost exceeds the two logistic regressions in AUC-ROC by about 0.007, a difference whose interval excludes zero, but it does not differ from the additive model and its AUC-PR does not differ from any model except the random forest. The relation between these predictors and credit is therefore close to additive, and the choice of algorithm matters little; we use XGBoost mainly for its SHAP explanations."))
c.append(table("Comparison of Models on the Test Set", ["Model","AUC-ROC","95% interval","AUC-PR","95% interval"],
   filas_bench, [64,38,55,38,55], "Intervals: 1,000 bootstrap resamples of test clusters. All models use the same 14 predictors and training set."))
c.append(H2("Validation"))
c.append(B("Table IV summarizes the validation. The bootstrap intervals are narrow: AUC-ROC 0.798 (0.780 to 0.814), AUC-PR 0.367 (0.325 to 0.409) and MCC 0.307 (0.272 to 0.338). The calibration slope is 1.04 and the intercept -0.04, close to the ideal values of 1 and 0, and predicted and observed rates differ by 0.8 points on average across deciles. The model is calibrated to the sample: in the test set the weighted mean prediction is 10.3 percent against a weighted observed rate of 9.9 percent. Trained only with 2016 to 2023, the model keeps its performance on 2024 and 2025 (AUC-ROC 0.804). When a whole region is left out, AUC-ROC falls to between 0.730 and 0.779 while AUC-PR stays two to three times above the prevalence, so the model loses some accuracy when applied to a region with conditions not seen in training. With all 196,566 cleaned producers the cross-validated AUC-ROC is 0.801 (0.797 to 0.805), so the subsample did not reduce accuracy."))
c.append(table("Validation of the Model", ["Validation","Producers","AUC-ROC","AUC-PR (prevalence)"],
   [["Test set","9,969","0.798","0.367 (0.119)"],["95% bootstrap interval","n/a","0.780–0.814","0.325–0.409"],["Time: 2016–23 to 2024–25","17,249","0.804","0.376 (0.120)"],
    ["Space: coast left out","10,401","0.730","0.417 (0.214)"],["Space: highlands left out","29,143","0.779","0.250 (0.082)"],["Space: rainforest left out","10,293","0.737","0.304 (0.129)"],
    ["All cleaned data (grouped CV)","196,566",f1(FULL['auc_roc'],3),f"{f1(FULL['auc_pr'],3)} ({f1(FULL['azar'],3)})"]], [82,48,54,66],
   "Prevalence (in parentheses): AUC-PR of a random ranking. Time, space and full-data rows refit the model with the selected configuration."))
c.append(H2("Factors Associated with Credit"))
c.append(B("Fig. 1 ranks the 14 variables by mean absolute SHAP value. Harvested area is the most important, followed by age, department, household size and fertilizer use. In terms of predicted probability, association membership adds 7.1 percentage points, moving from 0.27 to 2.43 harvested hectares (first to third quartile) adds 6.0, fertilizer use adds 4.1, and moving from 45 to 65 years of age subtracts 2.6."))
c.append(figure('fig1_shap.png', "Importance of the 14 selected variables (mean absolute SHAP value, test set).", 2.7))
c.append(B("The logistic regression gives the same direction for these effects. The odds of holding credit are about twice as high for association members (odds ratio 2.12; cluster-robust 95 percent interval 1.89 to 2.37). The odds also increase with harvested area (1.64 per log unit), fertilizer use (1.62), land renting (1.51) and pesticide use (1.41), and decrease with age (0.83 per ten years); robust intervals are only slightly wider than conventional ones. The odds ratios for the highlands (0.66) and the rainforest (0.75) relative to the coast are estimated together with department indicators, so they rest mainly on departments that span more than one region; without department indicators they are similar (0.67 and 0.79). The odds ratio for association membership is close to the estimate of more than two obtained with census data for small coffee farmers [[paredes]], although that study measured applying for credit rather than obtaining it; in our data the two outcomes are close because most applicants obtain credit."))
c.append(H2("Public and Private Lenders"))
c.append(B("Table V gives the borrowers of each type per 100 producers. Regulated private lenders are the largest source (5.1 per 100 producers in 2016 and 4.3 in 2025), followed by municipal savings banks (between 2.4 and 3.3) and national public lenders. Public lending fell from 2.0 per 100 producers in 2017 to 0.6 in 2019 and then recovered to 2.5 in 2025, when it served 25 percent of all borrowers. The fall coincides with the financial crisis of Agrobanco, which reported large losses in 2017 and 2018 [[agrobanco]]. Other lenders did not fill the gap. Among the quarter of producers whose profile most resembled Agrobanco clients, borrowing from Agrobanco fell from 5.4 to 1.4 percent between 2017 and 2019, borrowing from other lenders stayed at about 13 percent (12.7 and 12.9), and total access fell from 18.2 to 14.3 percent; among the other producers, access fell from 9.5 to 7.7 percent."))
c.append(table("Borrowers by Type of Lender per 100 Producers (Weighted)", ["Year","Public","Munic.","Private","Coop./NGO","Any"],
   [r[:5] + r[6:] for r in filas_lend], [30,44,44,44,50,40],
   "Public: Agrobanco and State programs. Munic.: municipal savings banks. Any: borrowers from any lender, including informal lenders (0.2 to 0.6 per 100 producers, not shown). Private: banks, rural savings banks and finance companies. A producer may use more than one type, so the columns do not add up to the total. All 196,566 cleaned producers, weighted."))
c.append(B("Public lenders do not serve the producers least likely to obtain credit. Their clients have a mean predicted probability of 23.1 percent, against 19.7 percent for regulated private lenders, and 11.8 percent of them are below the median propensity, against 21.5 percent. Relative to private clients and with the other predictors fixed, public clients have higher odds of being association members (odds ratio 2.33; 95 percent interval 2.09 to 2.61) and of farming in the highlands (1.32) or the rainforest (1.23), and lower odds of renting land (0.66). Public credit is used more often for agricultural inputs (76 percent of its clients, against 60 percent). The lender mix also differs by department: 32 percent of borrowers in Lambayeque use informal lenders, 47 percent in Apurimac use cooperatives, and more than half in Tumbes and Madre de Dios use municipal savings banks."))
c.append(H2("Targeting"))
c.append(B("Fig. 2 shows the cumulative gain curve. The 10 percent of producers with the highest predicted probability contains 36 percent of all credit holders; the top 20 percent contains 54 percent and the top 30 percent, 67 percent. In the top decile, 43 of every 100 producers hold credit, 3.6 times the rate of a random selection."))
c.append(figure('fig2_gain.png', "Cumulative gain: share of credit holders captured by coverage level. The dashed line is a random selection.", 2.4))
c.append(H2("Propensity Gap"))
c.append(B("Of the 9,969 test producers, 1,636 (16.4 percent of all producers, or 18.6 percent of those without credit) have no credit although the model assigns them a probability at or above the threshold. Table VI compares them with credit holders and with the remaining producers. The gap group harvests more than three hectares and most use fertilizers, but this similarity to credit holders follows from how the group is defined. The survey adds what the model cannot: only 1.9 percent of the gap group applied for credit, against 0.7 percent of the rest, so the gap is made of producers who did not seek credit rather than of applicants who were turned down."))
c.append(table("Profile of Producer Groups (Test Set)", ["Characteristic","With credit","Gap","Rest"],
   [["Producers","1,187","1,636","7,146"],["Applied for credit (%)","100.0","1.9","0.7"],["Harvested area, median (ha)","2.50","3.16","0.55"],["Mean age (years)","50.4","50.4","56.3"],["Association members (%)","15.1","19.6","2.7"],
    ["Use fertilizers (%)","79.8","88.1","47.2"],["Sell to regional markets (%)","50.5","53.9","18.0"],["Irrigated crops (%)","59.5","61.8","38.0"],["Located on the coast (%)","40.4","44.4","12.6"],["Located in the highlands (%)","39.3","30.7","66.7"]],
   [112,46,44,40], "Gap: no credit and predicted probability at or above the threshold (the false positives of the model). Rest: no credit and probability below it."))
c.append(B("The size of the gap depends on the threshold (Table VII): it ranges from 32.3 percent of producers at a threshold of 0.10 to 5.8 percent at 0.30. At every threshold, at most 2.2 percent of the gap applied for credit, and the ranking of departments changes little (Spearman correlation of 0.90 or more with the ranking at 0.175)."))
c.append(table("Sensitivity of the Propensity Gap to the Threshold (Test Set)", ["Threshold","Gap (%)","Precision (%)","Applied, in gap (%)","Department rank corr."],
   filas_sens, [46,40,48,56,62], "Gap: share of all test producers. 0.175 is the threshold used in the paper. Precision: share of producers above the threshold who hold credit. Rank correlation: Spearman correlation between department shares at this threshold and at 0.175."))
c.append(B("Table VIII gives the result by department with the full data. The gap is largest in Tumbes (46.7 percent of its producers; interval 44.6 to 48.6), Lambayeque (33.8) and Tacna (33.4), and smallest in Loreto (1.6), Ancash (4.6) and Huanuco (6.4). The department ranking agrees with the test-set ranking (Spearman correlation 0.93). The wide and asymmetric test-set interval for Tacna came from two clusters that held half of its test producers; with the full data its interval is 30.6 to 36.0. The gap closely follows the credit rate of each department (Spearman correlation 0.98): it is largest where credit is already common, so it reflects the department effect and the base rate rather than unserved regions."))
c.append(table("Credit Rate and Propensity Gap by Department (All Cleaned Data)", ["Department","n","Clusters","Credit (%)","Gap (%)","95% interval"],
   filas_dep(sin_tilde), [62,34,40,38,38,40],
   "n: cleaned producers in the department. Gap: share of the department's producers who have no credit and an out-of-fold predicted probability at or above 0.175. Interval: bootstrap of clusters within the department."))
c.append(H2("Scenario Simulation"))
c.append(B("Table IX reports how the mean predicted rate would change if the test producers who lack each condition had it, and Fig. 3 gives the result by region. Unweighted, the baseline is 12.3 percent; weighted to the population, 10.3 percent. Association membership is associated with the largest increase in all three regions: the rate would reach 18.7 percent unweighted (95 percent interval 17.8 to 19.6) and 16.4 percent weighted, a gain of 6.5 points, but 93 percent of producers are not members, so this scenario extrapolates far from current conditions. Irrigation adds 1.5 points, market sales 1.2 and fertilizers 1.1. Only the rainforest shows a distinct pattern, with gains of 3.6 points for irrigation and 2.3 for fertilizers against 0.4 and 0.3 on the coast; the gains from market sales are similar across regions (0.8 to 1.3). The four conditions together add 12.8 points, more than the 10.3 obtained by adding the four separate gains, because the model includes interactions; this combined figure depends on the model most strongly."))
c.append(table("Simulated Access Rate by Scenario (Test Set)", ["Scenario","Lacking (%)","Rate (%)","95% interval","Weighted (%)","Gain (pp)"],
   [["Baseline","n/a","12.3","n/a","10.3","n/a"],["Association membership","93.1","18.7","17.8–19.6","16.4","6.5"],["Irrigation on all crops","62.7","13.8","12.9–14.5","11.9","1.5"],["Regional/Lima market sales","72.3","13.5","12.6–14.2","11.5","1.2"],
    ["Fertilizer use","42.2","13.4","12.6–14.2","11.3","1.1"],["Association + market","97.3","20.3","19.3–21.2","18.0","8.0"],["All four conditions","98.9","25.1","24.2–26.0","22.8","12.8"]], [60,44,28,46,46,28],
   "Rate and gain (pp, percentage points) are unweighted. Lacking: producers without at least one of the conditions in the scenario. Weighted: expansion factors of the sample."))
c.append(figure('fig3_scenarios.png', "Simulated increase in the credit access rate by scenario and natural region (percentage points).", 3.3))
c.append(H2("Budget-Constrained Allocation"))
c.append(B("Table X gives the expected new credit holders when association is promoted among K non-members without credit. Evaluated with an independent model, choosing producers by simulated gain and choosing them by predicted probability give almost the same result: 102 and 103 expected new credit holders with 1,000 interventions. The gain rule is slightly better with 500 and worse with 2,000. Both rules reach about 1.6 times the 65 obtained at random. Evaluated with the same model that selects the producers, the gain rule would appear to yield 143, which shows how much a model overrates its own choices. The producers chosen by gain are mostly in the highlands (44 percent) and the rainforest (43 percent)."))
c.append(table("Expected New Credit Holders by Budget (Test Set)", ["Budget","Simulated gain","Highest probability","Random","Same model"],
   filas_asig, [40,60,60,60,32],
   "Budget: number of producers who receive the intervention (association membership, among non-members without credit). Columns 2 to 4: one cross-fitted model selects and an independent model evaluates, with 95 percent bootstrap intervals. Same model: the gain rule selected and evaluated with the final model."))
c.append(H1("Discussion"))
c.append(B("The results support two uses of the model that answer different objectives. A lender that wants to place credit efficiently can rank producers by predicted probability, because the top 20 percent contains more than half of the credit holders. A program that wants to add new borrowers should look at producers who do not yet borrow, and there the evidence is more modest. The propensity gap is not an unmet demand in the usual sense: almost none of these producers applied, and denial is rare in the survey (8 percent of applicants), so the barrier lies before the application. Discouraged borrowing and risk rationing [[boucher]] are consistent with this pattern, but the survey does not tell us why these producers did not apply. Outreach that lowers the cost of applying, such as information, simpler procedures or products linked to producer organizations, is a reasonable response to test. Because the gap is largest where credit is already common, such as Tumbes, Lambayeque and Tacna, it points to where outreach may be easiest rather than to underserved regions."))
c.append(B("Association membership is the condition most strongly associated with credit in both models and in the scenarios, and joint access to credit and cooperative services has been associated with higher farm productivity [[kehinde]]. This association can run in several directions: cooperatives lend directly (8 percent of the loans in the sample), members may join in order to borrow, and better-off producers may be more likely both to join and to borrow. The scenarios therefore indicate where a program could pilot association-based credit, not how much credit it would create. The lender analysis points to one concrete channel: public lenders reach association members far more often than private lenders do, so part of the association with credit may reflect how Agrobanco lends. The 2019 episode adds a second lesson: when the public lender withdrew, private lenders did not take its clients, so the stability of public credit matters for access. The allocation exercise reconciles the two objectives: among non-members, choosing those with the highest predicted probability works as well as choosing by simulated gain, so a program can use the simpler rule. Apart from association, only the rainforest shows a clear additional role for irrigation and fertilizers. For producers with low predicted probability, who harvest about half a hectare, the model suggests that conventional credit is unlikely to reach them, and other instruments would have to be evaluated separately."))
c.append(B("On the methodological side, five different models reach almost the same accuracy, so the predictive signal in the survey, and not the algorithm, sets the limit. This is in line with the argument for inherently interpretable models in high-stakes decisions [[rudin]] and with evidence that machine learning does not always outperform standard models on survey data [[ifft,liu]]. A logistic regression or an additive model would support the same conclusions with greater transparency."))
c.append(B("The study has several limitations. First, the data are observational: model-agnostic interpretation methods can mislead when read causally or when features are dependent [[molnar,murdoch]], fertilizer use may be a consequence of credit, and the scenarios should be validated with pilot programs or designs that estimate causal and heterogeneous effects, such as matching [[paredes]] or causal forests [[wager]]. Second, the consistency rules removed records with lower credit rates, so the results apply to producers with agricultural activity and complete records. Third, models are unweighted and calibrated to the sample; national figures are weighted only where stated. Fourth, precision is 0.30, so the model is suitable for prioritizing groups but not for deciding individual cases. Fifth, the time and space checks reuse choices made with all years and regions. Finally, the survey has no information on the supply side, such as the distance to lenders, or on the reasons for not applying."))

c.append(H1("Conclusions"))
c.append(B("Fourteen survey variables rank Peruvian small and medium agricultural producers by their likelihood of holding credit with an AUC-ROC of about 0.80, and the result holds in bootstrap intervals, out of time, across regions and with all cleaned data. XGBoost, an additive model and logistic regressions perform alike, so the model can be kept simple. Access depends mainly on applying: the 16.4 percent of producers with high predicted probability and no credit almost never applied, and they concentrate where credit is already common. Association membership is the condition most associated with credit, but its effect is not identified causally. When public lending fell in 2019, no other lender replaced it, and public lenders reach mainly association members rather than the producers least likely to obtain credit. For a program with a fixed budget, choosing non-members with the highest predicted probability is as effective as a gain-based rule and about 1.6 times better than a random choice. Future work should measure why producers do not apply, add supply-side information and test association-based credit with experimental or quasi-experimental designs."))

